import express from 'express';
import bcrypt from 'bcryptjs';
import jwt from 'jsonwebtoken';
import { z } from 'zod';

process.env.JWT_SECRET = 'contoh-kunci-di-editor-minimal-32-karakter!';
const JWT_SECRET = process.env.JWT_SECRET;
if (!JWT_SECRET || JWT_SECRET.length < 32) throw new Error('JWT_SECRET wajib diisi, minimal 32 karakter');

const pengguna = [];
const Akun = z.object({ email: z.email().toLowerCase(), password: z.string().min(8) });
const tampil = ({ hashPassword, ...p }) => p;
function butuhLogin(req, res, next) {
  const [jenis, token] = (req.get('authorization') ?? '').split(' ');
  try {
    if (jenis !== 'Bearer') throw new Error();
    const isi = jwt.verify(token, JWT_SECRET, { algorithms: ['HS256'] });
    req.pengguna = pengguna.find((p) => p.id === Number(isi.sub));
    if (!req.pengguna) throw new Error();
    next();
  } catch {
    res.status(401).json({ error: 'Perlu login' });
  }
}
const butuhPeran = (peran) => (req, res, next) => (req.pengguna.peran === peran ? next() : res.status(403).json({ error: 'Tidak berhak' }));

const app = express();
app.use(express.json());
app.post('/auth/daftar', async (req, res) => {
  const h = Akun.safeParse(req.body);
  if (!h.success) return res.status(400).json({ error: 'Data tidak valid' });
  if (pengguna.some((p) => p.email === h.data.email)) return res.status(409).json({ error: 'Email sudah terdaftar' });
  const baru = { id: pengguna.length + 1, email: h.data.email, hashPassword: await bcrypt.hash(h.data.password, 10), peran: pengguna.length === 0 ? 'admin' : 'pelanggan' };
  pengguna.push(baru);
  res.status(201).json(tampil(baru));
});
app.post('/auth/masuk', async (req, res) => {
  const p = pengguna.find((x) => x.email === String(req.body.email).toLowerCase());
  if (!p || !(await bcrypt.compare(String(req.body.password), p.hashPassword))) return res.status(401).json({ error: 'Email atau password salah' });
  res.json({ token: jwt.sign({ sub: String(p.id) }, JWT_SECRET, { expiresIn: '15m' }) });
});
app.get('/saya', butuhLogin, (req, res) => res.json(tampil(req.pengguna)));
app.get('/admin/pengguna', butuhLogin, butuhPeran('admin'), (req, res) => res.json(pengguna.map(tampil)));
const server = app.listen(3000);

const u = 'http://localhost:3000';
const post = (jalur, body) => fetch(u + jalur, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
await post('/auth/daftar', { email: 'sari@toko.id', password: 'pemilikToko1' });
await post('/auth/daftar', { email: 'rina@toko.id', password: 'pelanggan123' });
const tokenRina = (await (await post('/auth/masuk', { email: 'rina@toko.id', password: 'pelanggan123' })).json()).token;
const tokenSari = (await (await post('/auth/masuk', { email: 'sari@toko.id', password: 'pemilikToko1' })).json()).token;
const get = (jalur, token) => fetch(u + jalur, { headers: { Authorization: `Bearer ${token}` } });
console.log(await (await get('/saya', tokenRina)).json());
console.log((await get('/admin/pengguna', tokenRina)).status);
console.log((await (await get('/admin/pengguna', tokenSari)).json()).map((p) => p.email));
server.close();

