function periksaKunci(kunci) {
  if (!kunci || kunci.length < 32) throw new Error('JWT_SECRET wajib diisi, minimal 32 karakter');
  return true;
}
try {
  periksaKunci('pendek');
} catch (e) {
  console.log(e.message);
}
console.log(periksaKunci('a'.repeat(32)));
